`validators.py`:

```
"""Validators V1..V6 over depot harness outputs.

Each class subclasses ``Check`` from ``checks_base`` and implements ``check(items)``.
Callers use ``VN().run(items)``. Malformed input raises ``ValueError``, which ``Check.run``
turns into a failed result, so malformed data never passes.

Standard library only.
"""
from __future__ import annotations

import math
from typing import Any

from checks_base import Check

# Notification types named in the depot spec: SUPPLIER_SUSPENDED (C17), EXPIRY (C13),
# REORDER (C14), AUDIT_MISMATCH (C22), OVERDRAWN (C20).
SPEC_NOTIFICATION_TYPES = frozenset(
    {"SUPPLIER_SUSPENDED", "EXPIRY", "REORDER", "AUDIT_MISMATCH", "OVERDRAWN"}
)


def _is_int(x: Any) -> bool:
    return isinstance(x, int) and not isinstance(x, bool)


def _require_keys(item: Any, keys: tuple, where: str) -> None:
    if not isinstance(item, dict):
        raise ValueError(f"{where}: expected a dict, got {type(item).__name__}")
    missing = [k for k in keys if k not in item]
    if missing:
        raise ValueError(f"{where}: missing keys {missing}")


def _same(a: Any, b: Any) -> bool:
    """Equality that treats two NaN floats as equal (both implementations saying NaN agree)."""
    if isinstance(a, float) and isinstance(b, float) and math.isnan(a) and math.isnan(b):
        return True
    return a == b


class V1(Check):
    """C26: every report row has value_cents == units * unit_cost."""

    name = "V1"
    ROW_KEYS = ("sku", "wh", "units", "value_cents", "unit_cost")

    def check(self, items):
        mismatches = []
        for i, row in enumerate(items):
            _require_keys(row, self.ROW_KEYS, f"row {i}")
            for k in ("sku", "wh"):
                if not isinstance(row[k], str):
                    raise ValueError(f"row {i}: {k} must be str")
            for k in ("units", "value_cents", "unit_cost"):
                if not _is_int(row[k]):
                    raise ValueError(f"row {i}: {k} must be int")
            expected = row["units"] * row["unit_cost"]
            if row["value_cents"] != expected:
                mismatches.append(
                    {
                        "index": i,
                        "sku": row["sku"],
                        "wh": row["wh"],
                        "expected_value_cents": expected,
                        "value_cents": row["value_cents"],
                    }
                )
        return (not mismatches), {"rows_checked": len(items), "mismatches": mismatches}


class V2(Check):
    """C32/C14/C17/C13/C20/C22: every spec notification type was seen across the runs."""

    name = "V2"

    def check(self, items):
        seen = set()
        for r, run in enumerate(items):
            if isinstance(run, (str, bytes, dict)) or not hasattr(run, "__iter__"):
                raise ValueError(f"run {r}: expected a list of notifications")
            for n, note in enumerate(run):
                if not isinstance(note, tuple) or len(note) == 0:
                    raise ValueError(f"run {r}, notification {n}: expected a non-empty tuple")
                seen.add(note[0])
        missing = sorted(SPEC_NOTIFICATION_TYPES - seen)
        seen_spec = sorted(SPEC_NOTIFICATION_TYPES & seen)
        return (not missing), {"runs_checked": len(items), "seen": seen_spec, "missing": missing}


class V3(Check):
    """C29: two runs with the same seed are identical."""

    name = "V3"

    def check(self, items):
        mismatched = []
        for i, pair in enumerate(items):
            _require_keys(pair, ("seed", "a", "b"), f"pair {i}")
            if not _is_int(pair["seed"]):
                raise ValueError(f"pair {i}: seed must be int")
            if not _same(pair["a"], pair["b"]):
                mismatched.append(pair["seed"])
        return (not mismatched), {"pairs_checked": len(items), "mismatched_seeds": mismatched}


class V4(Check):
    """C19: storage cost stayed within the budget on every day."""

    name = "V4"

    def check(self, items):
        over = []
        for i, day in enumerate(items):
            _require_keys(day, ("day", "storage_cost_cents", "budget_cents"), f"day {i}")
            for k in ("day", "storage_cost_cents", "budget_cents"):
                if not _is_int(day[k]):
                    raise ValueError(f"day {i}: {k} must be int")
            if day["storage_cost_cents"] > day["budget_cents"]:
                over.append(
                    {
                        "day": day["day"],
                        "storage_cost_cents": day["storage_cost_cents"],
                        "budget_cents": day["budget_cents"],
                    }
                )
        return (not over), {"days_checked": len(items), "over_budget": over}


class V5(Check):
    """Every clause has at least one test. Blank test names do not count."""

    name = "V5"

    def check(self, items):
        untested = []
        for i, entry in enumerate(items):
            _require_keys(entry, ("clause_id", "tests"), f"clause entry {i}")
            if not isinstance(entry["clause_id"], str):
                raise ValueError(f"clause entry {i}: clause_id must be str")
            tests = entry["tests"]
            if isinstance(tests, (str, bytes, dict)) or not hasattr(tests, "__iter__"):
                raise ValueError(f"clause entry {i}: tests must be a list of str")
            real = [t for t in tests if isinstance(t, str) and t.strip()]
            if not real:
                untested.append(entry["clause_id"])
        return (not untested), {"clauses_checked": len(items), "untested": untested}


class V6(Check):
    """Two implementations agree on every compared pair."""

    name = "V6"

    def check(self, items):
        disagreements = []
        for i, pair in enumerate(items):
            _require_keys(pair, ("key", "a", "b"), f"pair {i}")
            if not _same(pair["a"], pair["b"]):
                disagreements.append(pair["key"])
        return (not disagreements), {
            "pairs_checked": len(items),
            "disagreements": disagreements,
        }
```

`checks_base.py`:

```
"""The ``Check`` base class: a check never passes on nothing (brief 3, and E2's guard condition).

``Check.run(items)`` returns ``failed: empty input`` for empty or all-unmeasured input *before*
calling the subclass, and ``failed: nothing measured`` when the subclass measured nothing. The
harness's own checks (presence, reach, parity, mutation) subclass it, and so do the agent's
validators in E2's guard condition (the agent gets this file as ``checks_base.py``).

This file is standard-library only so it can be copied verbatim into the agent's repo.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Any


@dataclass
class CheckResult:
    passed: bool
    measured: Any
    reason: str = ""

    def __iter__(self):  # allows ``passed, measured = check.run(x)``
        yield self.passed
        yield self.measured

    def __bool__(self) -> bool:
        return bool(self.passed)


def is_empty(value: Any) -> bool:
    """True for None, empty containers, and containers whose every leaf is None or empty."""
    if value is None:
        return True
    if isinstance(value, (str, bytes)):
        return len(value) == 0
    if isinstance(value, dict):
        return len(value) == 0 or all(is_empty(v) for v in value.values())
    if isinstance(value, (list, tuple, set, frozenset)):
        return len(value) == 0 or all(is_empty(v) for v in value)
    return False


class Check:
    """Subclasses implement ``check(items) -> (passed, measured)``; callers use ``run(items)``."""

    name = "check"

    def run(self, items: Any) -> CheckResult:
        if hasattr(items, "__next__"):  # a lazy source of runs: materialise before judging emptiness
            items = list(items)
        if is_empty(items):
            return CheckResult(False, None, "failed: empty input")
        try:
            passed, measured = self.check(items)
        except Exception as exc:  # a check that crashes has not passed
            return CheckResult(False, None, f"failed: {type(exc).__name__}: {exc}")
        if is_empty(measured):
            return CheckResult(False, measured, "failed: nothing measured")
        return CheckResult(bool(passed), measured, "" if passed else "failed")

    def check(self, items: Any) -> tuple[bool, Any]:  # pragma: no cover - abstract
        raise NotImplementedError
```
